import ee
ee.Initialize()

def print_limit(s):
    print(s)

# Geometry: Kalahari Desert subset in Botswana
geom = ee.Geometry.Polygon(
    [[[22.0, -24.0], [24.0, -24.0], [24.0, -22.0], [22.0, -22.0], [22.0, -24.0]]],
    None, False
)

def modis_ndvi_stats(date_str, geom):
    target = ee.Date(date_str)
    def get_col(win_days):
        start = target.advance(-win_days, 'day')
        end = target.advance(win_days + 1, 'day')  # end-exclusive
        return (ee.ImageCollection('MODIS/061/MOD13Q1')
                .filterDate(start, end)
                .filterBounds(geom))
    col = get_col(8)
    size = col.size().getInfo()
    if size == 0:
        col = get_col(20)
        size = col.size().getInfo()
        if size == 0:
            return {'status':'C1'}
    # Pick composite closest to target date
    def add_diff(img):
        diff = img.date().millis().subtract(target.millis()).abs()
        return img.set('time_diff', diff)
    col = col.map(add_diff).sort('time_diff')
    img = ee.Image(col.first())
    used_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
    ndvi = img.select('NDVI').multiply(0.0001)
    qa = img.select('SummaryQA')
    mask = qa.lte(1)
    ndvi_m = ndvi.updateMask(mask)
    # Counts
    valid_count = ndvi_m.reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom, scale=1000, maxPixels=1e9
    ).get('NDVI').getInfo()
    total_count = ee.Image.constant(1).rename('one').reduceRegion(
        reducer=ee.Reducer.count(),
        geometry=geom, scale=1000, maxPixels=1e9
    ).get('one').getInfo()
    if valid_count is None or total_count is None:
        return {'status':'C3'}
    if valid_count == 0:
        return {'status':'C2'}
    mean_ndvi = ndvi_m.reduceRegion(
        reducer=ee.Reducer.mean(),
        geometry=geom, scale=1000, maxPixels=1e9
    ).get('NDVI').getInfo()
    if mean_ndvi is None or not (-0.2 <= mean_ndvi <= 1.0):
        return {'status':'C3'}
    clear_pct = 100.0 * valid_count / float(total_count)
    return {
        'status':'OK',
        'used_date': used_date,
        'images': size,
        'valid': int(valid_count),
        'total': int(total_count),
        'clear_pct': clear_pct,
        'mean_ndvi': mean_ndvi
    }

def landsat5_fallback(date_str, geom):
    target = ee.Date(date_str)
    def apply_scale(img):
        return img.addBands(img.select('SR_B.').multiply(0.0000275).add(-0.2), overwrite=True)
    def cloud_mask(img):
        cs = ee.Algorithms.Landsat.simpleCloudScore(img).select('cloud')
        return img.updateMask(cs.lt(20))
    col = (ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
           .filterBounds(geom)
           .filterDate(target.advance(-16,'day'), target.advance(17,'day'))
           .map(apply_scale)
           .map(cloud_mask))
    size = col.size().getInfo()
    if size == 0:
        return {'status':'C1'}
    # Choose closest in time
    def add_diff(img):
        diff = img.date().millis().subtract(target.millis()).abs()
        return img.set('time_diff', diff)
    img = ee.Image(col.map(add_diff).sort('time_diff').first())
    used_date = ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo()
    nir = img.select('SR_B4')
    red = img.select('SR_B3')
    ndvi = nir.subtract(red).divide(nir.add(red)).rename('NDVI')
    # Valid count
    valid_count = ndvi.reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=30*5, maxPixels=1e9
    ).get('NDVI').getInfo()
    total_count = ee.Image.constant(1).rename('one').reduceRegion(
        reducer=ee.Reducer.count(), geometry=geom, scale=30*5, maxPixels=1e9
    ).get('one').getInfo()
    if valid_count is None or total_count is None:
        return {'status':'C3'}
    if valid_count == 0:
        return {'status':'C2'}
    mean_ndvi = ndvi.reduceRegion(
        reducer=ee.Reducer.mean(), geometry=geom, scale=30*5, maxPixels=1e9
    ).get('NDVI').getInfo()
    if mean_ndvi is None or not (-1.0 <= mean_ndvi <= 1.0):
        return {'status':'C3'}
    clear_pct = 100.0 * valid_count / float(total_count)
    return {
        'status':'OK',
        'used_date': used_date,
        'images': size,
        'valid': int(valid_count),
        'total': int(total_count),
        'clear_pct': clear_pct,
        'mean_ndvi': mean_ndvi
    }

def get_stats(date_str):
    r = modis_ndvi_stats(date_str, geom)
    if r.get('status') == 'C1':
        r = landsat5_fallback(date_str, geom)
        r['source'] = 'Landsat5'
    elif r.get('status') == 'OK':
        r['source'] = 'MODIS'
    return r

try:
    print_limit("Region: Kalahari bbox [22E,24E] x [24S,22S], scale=1000m")
    d1 = '2008-08-06'
    d2 = '2009-04-19'

    r1 = get_stats(d1)
    if r1['status'] != 'OK':
        print_limit(f"{d1}: Status {r1['status']}")
        print(r1['status'])
        raise SystemExit()

    r2 = get_stats(d2)
    if r2['status'] != 'OK':
        print_limit(f"{d2}: Status {r2['status']}")
        print(r2['status'])
        raise SystemExit()

    print_limit(f"{d1}: {r1['source']} images: {r1['images']}, used: {r1['used_date']}")
    print_limit(f"  Valid px: {r1['valid']}/{r1['total']} ({r1['clear_pct']:.1f}%), NDVI mean: {r1['mean_ndvi']:.3f}")
    print_limit(f"{d2}: {r2['source']} images: {r2['images']}, used: {r2['used_date']}")
    print_limit(f"  Valid px: {r2['valid']}/{r2['total']} ({r2['clear_pct']:.1f}%), NDVI mean: {r2['mean_ndvi']:.3f}")

    greener = (r2['mean_ndvi'] > r1['mean_ndvi'])
    print_limit(f"Greener on {d2} than {d1}? {greener}")

    # Final tag
    print("A" if greener else "B")

except ee.EEException as e:
    print_limit(f"Error: {str(e)[:120]}")
    print("D")
except Exception as e:
    # If we earlier printed a code (C1/C2/C3), SystemExit is raised; otherwise generic error
    if str(e):
        # Avoid extra prints if already handled
        pass

